def compute(vars):
    old_assets = vars["v1"]
    new_assets = vars["v2"]
    change = new_assets - old_assets
    return {
        "value": change,
        "trace": {
            "old_assets": old_assets,
            "new_assets": new_assets,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
